'use client'
import { useState, useEffect } from 'react'

const LOGO_SRC = 'data:image/png;base64,'

type TravelType = 'air' | 'package'
interface Traveler { age: string; cabin: string }

export default function CotizadorPage() {
  const [lang, setLang] = useState<'es'|'en'>('es')
  const [travelType, setTravelType] = useState<TravelType>('air')
  const [origin, setOrigin] = useState('')
  const [dest, setDest] = useState('')
  const [dateOut, setDateOut] = useState('')
  const [dateRet, setDateRet] = useState('')
  const [flexible, setFlexible] = useState('no')
  const [travelers, setTravelers] = useState<Traveler[]>([{ age: 'adult', cabin: 'economy' }])
  const [luggage, setLuggage] = useState(false)
  const [luggageCount, setLuggageCount] = useState('1')
  const [budget, setBudget] = useState('')
  const [notes, setNotes] = useState('')
  const [contactName, setContactName] = useState('')
  const [contactPhone, setContactPhone] = useState('')
  const [dateError, setDateError] = useState('')
  const [today, setToday] = useState('')

  useEffect(() => { setToday(new Date().toISOString().split('T')[0]) }, [])

  const labels = {
    es: { air: 'Boletos Aéreos', pkg: 'Paquete Premium', adult: 'Adulto (18+)', youth: 'Joven (12-17)', child: 'Niño (2-11)', infant: 'Bebé (0-1)', economy: 'Económica', premium: 'Económica Premium', business: 'Clase Ejecutiva', first: 'Primera Clase', flexNo: 'No, fechas exactas', flexFew: 'Sí, ±2-3 días', flexWeek: 'Sí, ±1 semana', lt500: 'Menos de $500', b500: '$500 - $1,000', b1000: '$1,000 - $2,500', b2500: '$2,500 - $5,000', b5000: 'Más de $5,000' },
    en: { air: 'Air Tickets', pkg: 'Premium Package', adult: 'Adult (18+)', youth: 'Youth (12-17)', child: 'Child (2-11)', infant: 'Infant (0-1)', economy: 'Economy', premium: 'Premium Economy', business: 'Business Class', first: 'First Class', flexNo: 'No, exact dates', flexFew: 'Yes, ±2-3 days', flexWeek: 'Yes, ±1 week', lt500: 'Less than $500', b500: '$500 - $1,000', b1000: '$1,000 - $2,500', b2500: '$2,500 - $5,000', b5000: 'More than $5,000' }
  }
  const L = labels[lang]

  const addTraveler = () => { if (travelers.length < 12) setTravelers([...travelers, { age: 'adult', cabin: 'economy' }]) }
  const removeTraveler = (i: number) => { if (travelers.length > 1) setTravelers(travelers.filter((_,idx) => idx !== i)) }
  const updateTraveler = (i: number, field: keyof Traveler, val: string) => {
    const updated = [...travelers]; updated[i] = { ...updated[i], [field]: val }; setTravelers(updated)
  }

  const validateDates = (out: string, ret: string) => {
    if (out && ret && ret < out) { setDateError(lang === 'es' ? 'La fecha de regreso no puede ser anterior a la de salida.' : 'Return date cannot be before departure date.'); return false }
    setDateError(''); return true
  }

  const formatDate = (d: string) => {
    if (!d) return lang === 'es' ? 'No especificada' : 'Not specified'
    const [y,m,day] = d.split('-'); return `${day}/${m}/${y}`
  }

  const sendQuote = () => {
    if (!origin.trim() || !dest.trim() || !dateOut || !contactName.trim() || !contactPhone.trim()) {
      alert(lang === 'es' ? 'Por favor completa los campos obligatorios.' : 'Please complete all required fields.'); return
    }
    if (!validateDates(dateOut, dateRet)) return
    const typeLabel = travelType === 'air' ? L.air : L.pkg
    const flexLabel: Record<string,string> = { no: L.flexNo, few: L.flexFew, week: L.flexWeek }
    const budgetLabel: Record<string,string> = { lt500: L.lt500, '500-1000': L.b500, '1000-2500': L.b1000, '2500-5000': L.b2500, '5000+': L.b5000 }
    const travelersDetail = travelers.map((tr, i) => {
      const cabin = travelType === 'air' ? ` - ${L[tr.cabin as keyof typeof L]}` : ''
      return `   ${i+1}. ${L[tr.age as keyof typeof L]}${cabin}`
    }).join('\n')
    const msg = lang === 'es'
      ? `Hola Genius VC Travel, me gustaria cotizar un viaje:\n\nTIPO: ${typeLabel}\nORIGEN: ${origin}\nDESTINO: ${dest}\n\nFECHA DE SALIDA: ${formatDate(dateOut)}\nFECHA DE REGRESO: ${formatDate(dateRet)}\nFLEXIBILIDAD: ${flexLabel[flexible] || flexible}\n\nVIAJEROS (${travelers.length}):\n${travelersDetail}${travelType === 'air' && luggage ? `\nMALETAS: ${luggageCount}` : ''}${budget ? `\nPRESUPUESTO: ${budgetLabel[budget] || budget}` : ''}${notes ? `\nPREFERENCIAS: ${notes}` : ''}\n\nCONTACTO: ${contactName}\nTELEFONO: ${contactPhone}`
      : `Hello Genius VC Travel, I would like a travel quote:\n\nTYPE: ${typeLabel}\nFROM: ${origin}\nTO: ${dest}\n\nDEPARTURE: ${formatDate(dateOut)}\nRETURN: ${formatDate(dateRet)}\nFLEXIBILITY: ${flexLabel[flexible] || flexible}\n\nTRAVELERS (${travelers.length}):\n${travelersDetail}${travelType === 'air' && luggage ? `\nBAGS: ${luggageCount}` : ''}${budget ? `\nBUDGET: ${budgetLabel[budget] || budget}` : ''}${notes ? `\nPREFERENCES: ${notes}` : ''}\n\nNAME: ${contactName}\nPHONE: ${contactPhone}`
    window.location.href = `https://wa.me/50497410936?text=${encodeURIComponent(msg)}`
  }

  const ic = 'w-full rounded-xl border border-white/15 bg-white/5 px-4 py-3 text-sm text-white outline-none focus:border-[#C9A84C] placeholder:text-white/30'
  const sc = 'w-full rounded-xl border border-white/15 bg-[#1A3A3A] px-4 py-3 text-sm text-white outline-none focus:border-[#C9A84C] [&>option]:bg-[#1A3A3A]'
  const lc = 'block text-sm font-semibold text-white/85 mb-2'

  return (
    <main className='min-h-screen bg-[#1A3A3A]'>
      <header className='bg-[#0D2222] border-b border-white/10'>
        <div className='mx-auto max-w-2xl px-4 py-4 flex items-center justify-between'>
          <img src={LOGO_SRC} alt='Genius VC Travel' className='h-12 w-auto object-contain' />
          <div className='flex items-center gap-2'>
            {['es','en'].map(l => (
              <button key={l} onClick={() => setLang(l as 'es'|'en')} className={`text-xs px-3 py-1.5 rounded-full border ${lang===l?'border-[#C9A84C] text-[#C9A84C]':'border-white/20 text-white/50'}`}>{l.toUpperCase()}</button>
            ))}
            <a href='/viajes' className='text-xs text-white/40 hover:text-white/70 ml-2'>{lang==='es'?'← Volver':'← Back'}</a>
          </div>
        </div>
      </header>

      <div className='mx-auto max-w-2xl px-4 py-8'>
        <h1 className='text-2xl font-bold text-white mb-1'>{lang==='es'?'Cotiza tu próximo viaje':'Quote your next trip'}</h1>
        <p className='text-sm text-white/50 mb-8'>{lang==='es'?'Cuéntanos qué necesitas y te contactamos con la mejor opción':'Tell us what you need and we will contact you with the best option'}</p>

        <div className='grid grid-cols-2 gap-3 mb-8'>
          {(['air','package'] as TravelType[]).map(type => (
            <button key={type} onClick={() => setTravelType(type)} className={`rounded-2xl border-2 p-5 text-center transition-all ${travelType===type?'border-[#C9A84C] bg-[#C9A84C]/10':'border-white/10 bg-white/5 hover:border-white/20'}`}>
              <div className='text-3xl mb-2'>{type==='air'?'✈️':'🌴'}</div>
              <div className={`text-sm font-bold ${travelType===type?'text-[#C9A84C]':'text-white'}`}>{type==='air'?L.air:L.pkg}</div>
            </button>
          ))}
        </div>

        <div className='space-y-5'>
          <div><label className={lc}>{lang==='es'?'Ciudad de origen':'City of origin'} <span className='text-[#C9A84C]'>*</span></label><input type='text' value={origin} onChange={e=>setOrigin(e.target.value)} placeholder={lang==='es'?'Ej. Tegucigalpa':'E.g. Tegucigalpa'} className={ic} /></div>
          <div><label className={lc}>{lang==='es'?'Destino(s)':'Destination(s)'} <span className='text-[#C9A84C]'>*</span></label><input type='text' value={dest} onChange={e=>setDest(e.target.value)} placeholder={lang==='es'?'Ej. Miami, Orlando':'E.g. Miami, Orlando'} className={ic} /></div>

          <div className='grid grid-cols-2 gap-3'>
            <div><label className={lc}>{lang==='es'?'Fecha de salida':'Departure date'} <span className='text-[#C9A84C]'>*</span></label><input type='date' value={dateOut} min={today} onChange={e=>{setDateOut(e.target.value);validateDates(e.target.value,dateRet)}} className={ic+' [color-scheme:dark]'} /></div>
            <div><label className={lc}>{lang==='es'?'Fecha de regreso':'Return date'}</label><input type='date' value={dateRet} min={dateOut||today} onChange={e=>{setDateRet(e.target.value);validateDates(dateOut,e.target.value)}} className={ic+' [color-scheme:dark]'} /></div>
          </div>
          {dateError && <p className='text-red-400 text-xs -mt-3'>{dateError}</p>}

          <div><label className={lc}>{lang==='es'?'¿Sus fechas son flexibles?':'Are your dates flexible?'}</label>
            <select value={flexible} onChange={e=>setFlexible(e.target.value)} className={sc}>
              <option value='no'>{L.flexNo}</option>
              <option value='few'>{L.flexFew}</option>
              <option value='week'>{L.flexWeek}</option>
            </select>
          </div>

          <div>
            <div className='flex items-center justify-between mb-3'>
              <label className={lc+' mb-0'}>{lang==='es'?'Viajeros':'Travelers'} <span className='text-[#C9A84C]'>*</span></label>
              <button onClick={addTraveler} className='text-xs text-[#C9A84C] border border-[#C9A84C]/30 px-3 py-1 rounded-full hover:bg-[#C9A84C]/10'>{lang==='es'?'+ Agregar viajero':'+ Add traveler'}</button>
            </div>
            <div className='space-y-2'>
              {travelers.map((tr, i) => (
                <div key={i} className='flex items-center gap-2 bg-white/4 border border-white/8 rounded-xl p-3'>
                  <span className='text-xs font-bold text-[#C9A84C] w-6'>{i+1}</span>
                  <select value={tr.age} onChange={e=>updateTraveler(i,'age',e.target.value)} className='flex-1 bg-white/8 border border-white/10 rounded-lg px-3 py-2 text-xs text-white [&>option]:bg-[#1A3A3A] outline-none'>
                    <option value='adult'>{L.adult}</option>
                    <option value='youth'>{L.youth}</option>
                    <option value='child'>{L.child}</option>
                    <option value='infant'>{L.infant}</option>
                  </select>
                  {travelType==='air' && <select value={tr.cabin} onChange={e=>updateTraveler(i,'cabin',e.target.value)} className='flex-1 bg-white/8 border border-white/10 rounded-lg px-3 py-2 text-xs text-white [&>option]:bg-[#1A3A3A] outline-none'>
                    <option value='economy'>{L.economy}</option>
                    <option value='premium'>{L.premium}</option>
                    <option value='business'>{L.business}</option>
                    <option value='first'>{L.first}</option>
                  </select>}
                  {travelers.length > 1 && <button onClick={()=>removeTraveler(i)} className='text-xs text-white/30 hover:text-red-400 px-2'>×</button>}
                </div>
              ))}
            </div>
          </div>

          {travelType==='air' && (
            <div>
              <label className={lc}>{lang==='es'?'¿Necesitan maletas registradas?':'Do you need checked luggage?'}</label>
              <label className='flex items-center gap-3 bg-white/5 border border-white/10 rounded-xl px-4 py-3 cursor-pointer'>
                <input type='checkbox' checked={luggage} onChange={e=>setLuggage(e.target.checked)} className='accent-[#C9A84C]' />
                <span className='text-sm text-white/80'>{lang==='es'?'Sí, necesitamos maletas registradas':'Yes, we need checked luggage'}</span>
              </label>
              {luggage && <select value={luggageCount} onChange={e=>setLuggageCount(e.target.value)} className={sc+' mt-2'}>
                {['1','2','3','4','5+'].map(n=><option key={n} value={n}>{n} {lang==='es'?`maleta${n==='1'?'':'s'}`:`bag${n==='1'?'':'s'}`}</option>)}
              </select>}
            </div>
          )}

          <div><label className={lc}>{lang==='es'?'Presupuesto por persona':'Budget per person'}</label>
            <select value={budget} onChange={e=>setBudget(e.target.value)} className={sc}>
              <option value=''>-- {lang==='es'?'Seleccionar':'Select'} --</option>
              <option value='lt500'>{L.lt500}</option>
              <option value='500-1000'>{L.b500}</option>
              <option value='1000-2500'>{L.b1000}</option>
              <option value='2500-5000'>{L.b2500}</option>
              <option value='5000+'>{L.b5000}</option>
            </select>
          </div>

          <div><label className={lc}>{lang==='es'?'Preferencias adicionales':'Additional preferences'}</label><textarea value={notes} onChange={e=>setNotes(e.target.value)} placeholder={lang==='es'?'Hotel frente al mar, primera clase...':'Beachfront hotel, first class...'} className={ic+' resize-y min-h-[80px]'} /></div>

          <div className='pt-4 border-t border-white/10'>
            <p className='text-xs font-bold uppercase tracking-widest text-[#C9A84C] mb-4'>{lang==='es'?'Tus datos de contacto':'Your contact details'}</p>
            <div className='space-y-3'>
              <div><label className={lc}>{lang==='es'?'Tu nombre':'Your name'} <span className='text-[#C9A84C]'>*</span></label><input type='text' value={contactName} onChange={e=>setContactName(e.target.value)} placeholder={lang==='es'?'Tu nombre completo':'Your full name'} className={ic} /></div>
              <div><label className={lc}>{lang==='es'?'WhatsApp / Teléfono':'WhatsApp / Phone'} <span className='text-[#C9A84C]'>*</span></label><input type='tel' value={contactPhone} onChange={e=>setContactPhone(e.target.value)} placeholder='+504 XXXX-XXXX' className={ic} /></div>
            </div>
          </div>

          <button onClick={sendQuote} className='w-full flex items-center justify-center gap-2 rounded-full bg-[#25D366] py-4 text-sm font-bold text-white mt-2 hover:opacity-90 transition-opacity'>
            <svg width='18' height='18' viewBox='0 0 24 24' fill='white'><path d='M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413z'/></svg>
            {lang==='es'?'Enviar cotización por WhatsApp':'Send quote via WhatsApp'}
          </button>
          <p className='text-center text-xs text-white/40 mt-2'>{lang==='es'?'Se abrirá WhatsApp con tu solicitud':'WhatsApp will open with your request'}</p>
        </div>

        <div className='mt-12 pt-6 border-t border-white/10 text-center'>
          <div className='flex flex-wrap justify-center gap-4 mb-3'>
            <a href='tel:+50497410936' className='text-xs text-white/40 hover:text-white/60'>+504 9741-0936</a>
            <a href='mailto:geniusvisac@gmail.com' className='text-xs text-white/40 hover:text-white/60'>geniusvisac@gmail.com</a>
            <a href='https://geniusvctravel.com' className='text-xs text-white/40 hover:text-white/60'>geniusvctravel.com</a>
          </div>
          <p className='text-xs text-white/25'>© 2026 Genius VC Travel · Tegucigalpa, Honduras</p>
        </div>
      </div>
    </main>
  )
}
